import { useCallback, useSyncExternalStore } from "react";
import useEmblaCarousel from "embla-carousel-react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import {
  Card,
  CardContent,
  CardDescription,
  CardTitle,
} from "@/components/custom/blocks/CardBlock";
import { Badge } from "@/components/custom/ui/badge";
import Button from "@/components/custom/blocks/Button";
import { accentStyle } from "@/lib/accent";
import { cn } from "@/lib/utils";

const products = [
  { name: "Aurora Desk Lamp", price: "$129", tag: "New", image: "https://res.cloudinary.com/dodndg7ai/image/upload/f_webp,q_auto,w_800,c_limit/v1790159966/photo-1507473885765-e6ed057f782c-1790159970112.jpg" },
  { name: "Vector Keyboard", price: "$189", tag: "Popular", image: "https://res.cloudinary.com/dodndg7ai/image/upload/f_webp,q_auto,w_800,c_limit/v1790159967/photo-1587829741301-dc798b83add3-1790159970115.jpg" },
  { name: "Halo Wireless Mouse", price: "$99", tag: "Restocked", image: "https://res.cloudinary.com/dodndg7ai/image/upload/f_webp,q_auto,w_800,c_limit/v1790159966/photo-1527864550417-7fd91fc51a46-1790159970113.jpg" },
  { name: "Drift Office Chair", price: "$349", tag: "Bestseller", image: "https://res.cloudinary.com/dodndg7ai/image/upload/f_webp,q_auto,w_800,c_limit/v1790159966/photo-1580480055273-228ff5388ef8-1790159970114.jpg" },
  { name: "Pulse Device Hub", price: "$149", tag: "New", image: "https://res.cloudinary.com/dodndg7ai/image/upload/f_webp,q_auto,w_800,c_limit/v1790159967/photo-1596742578443-7682ef5251cd-1790159970115.jpg" },
];

/**
 * Embla ships no markup and no CSS of its own: it hands back a ref and an API
 * object, and the track, the slides, the arrows and the dots are all yours.
 * That means the controls here are ordinary `Button`s and each slide is an
 * ordinary `Card` — nothing is being restyled or overridden.
 */
export default function EmblaProductCarousel({ color }: { color?: string } = {}) {
  const [emblaRef, emblaApi] = useEmblaCarousel({ loop: true, align: "start" });

  const scrollTo = useCallback((index: number) => emblaApi?.scrollTo(index), [emblaApi]);

  // Embla is an external store: read the active snap and the number of snaps
  // straight from the API, and re-read them whenever it fires `select` or
  // `reInit` (a resize can change how many snaps there are).
  const subscribe = useCallback(
    (onChange: () => void) => {
      if (!emblaApi) return () => {};
      emblaApi.on("select", onChange).on("reInit", onChange);
      return () => {
        emblaApi.off("select", onChange).off("reInit", onChange);
      };
    },
    [emblaApi],
  );
  const selected = useSyncExternalStore(
    subscribe,
    () => emblaApi?.selectedScrollSnap() ?? 0,
    () => 0,
  );
  // The snap list only exists once embla has measured the slides.
  const snapCount = useSyncExternalStore(
    subscribe,
    () => emblaApi?.scrollSnapList().length ?? 0,
    () => 0,
  );

  return (
    <div className="w-full max-w-4xl" style={accentStyle(color)}>
      <div className="mb-4 flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold text-foreground">Featured products</h3>
          <p className="text-sm text-muted-foreground">Drag, swipe or use the arrows</p>
        </div>
        <div className="flex gap-2">
          <Button
            size="sm"
            variant="outline"
            className="h-9 w-9 justify-center p-0 hover:border-primary/50 hover:text-primary transition-colors cursor-pointer"
            aria-label="Previous slide"
            iconLeft={<ChevronLeft className="h-4 w-4" />}
            onClick={() => emblaApi?.scrollPrev()}
          />
          <Button
            size="sm"
            variant="outline"
            className="h-9 w-9 justify-center p-0 hover:border-primary/50 hover:text-primary transition-colors cursor-pointer"
            aria-label="Next slide"
            iconLeft={<ChevronRight className="h-4 w-4" />}
            onClick={() => emblaApi?.scrollNext()}
          />
        </div>
      </div>

      {/* The viewport clips; the track is a flex row Embla translates. */}
      <div className="overflow-hidden" ref={emblaRef}>
        <div className="flex touch-pan-y gap-4">
          {products.map((product) => (
            <div
              key={product.name}
              className="min-w-0 shrink-0 grow-0 basis-[80%] sm:basis-[48%] lg:basis-[32%]"
            >
              <Card interactive className="h-full overflow-hidden">
                <img
                  src={product.image}
                  alt={product.name}
                  className="h-40 w-full object-cover"
                  loading="lazy"
                />
                <CardContent className="pt-4">
                  <Badge variant="outline" className="mb-2 border-primary/25 bg-primary/10 text-primary font-medium">
                    {product.tag}
                  </Badge>
                  <CardTitle className="text-base">{product.name}</CardTitle>
                  <CardDescription>{product.price}</CardDescription>
                </CardContent>
              </Card>
            </div>
          ))}
        </div>
      </div>

      <div className="mt-4 flex justify-center gap-2">
        {Array.from({ length: snapCount }, (_, index) => (
          <button
            key={index}
            type="button"
            aria-label={`Go to slide ${index + 1}`}
            onClick={() => scrollTo(index)}
            className={cn(
              "h-1.5 rounded-full transition-all cursor-pointer",
              index === selected ? "w-6 bg-primary" : "w-1.5 bg-border hover:bg-primary/40",
            )}
          />
        ))}
      </div>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import React from "react";

// ==========================================
// 1. ROOT CARD WRAPPER
// ==========================================
export interface CardProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: "default" | "bordered" | "flat";
  interactive?: boolean;
}

export function Card({
  className,
  variant = "bordered",
  interactive = false,
  children,
  ...props
}: CardProps) {
  const variants = {
    default: "bg-card shadow-sm border border-primary/10",
    bordered:
      "bg-card border border-primary/25 shadow-sm",
    flat: "bg-muted border border-primary/20",
  };

  return (
    <div
      className={cn(
        "rounded-xl text-card-foreground flex flex-col transition-all duration-200",
        variants[variant],
        interactive &&
          "hover:shadow-md hover:-translate-y-0.5 cursor-pointer hover:border-primary/50 active:scale-[0.98]",
        className,
      )}
      {...props}
    >
      {children}
    </div>
  );
}

// ==========================================
// 2. HEADER
// ==========================================
export function CardHeader({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div className={cn("flex flex-col space-y-1.5 p-6", className)} {...props}>
      {children}
    </div>
  );
}

export function CardTitle({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLHeadingElement>) {
  return (
    <h3
      className={cn(
        "font-semibold leading-none tracking-tight text-lg",
        className,
      )}
      {...props}
    >
      {children}
    </h3>
  );
}

export function CardDescription({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLParagraphElement>) {
  return (
    <p
      className={cn("text-sm text-muted-foreground", className)}
      {...props}
    >
      {children}
    </p>
  );
}

// ==========================================
// 3. CONTENT AREA
// ==========================================
export function CardContent({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div className={cn("p-6 pt-0 flex-1", className)} {...props}>
      {children}
    </div>
  );
}

// ==========================================
// 4. FOOTER
// ==========================================
export function CardFooter({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn("flex items-center p-6 pt-0 mt-auto", className)}
      {...props}
    >
      {children}
    </div>
  );
}

// Re-export ProductCard for convenient unified importing from CardBlock
export { ProductCard } from "@/components/custom/blocks/ProductCardBlock";
export type { ProductCardProps, ProductColorOption } from "@/components/custom/blocks/ProductCardBlock";

"use client";

import React, { useState } from "react";
import { cn } from "@/lib/utils";
import {
  Heart,
  ShoppingCart,
  Star,
  Zap,
  CheckCircle2,
  Plus,
  Eye,
} from "lucide-react";

export type ProductCardVariant = "standard" | "compact" | "horizontal";

export interface ProductColorOption {
  name: string;
  value: string; // Tailwind color class or hex string (e.g. 'bg-indigo-600')
}

export interface ProductCardProps {
  className?: string;
  variant?: ProductCardVariant;
  title: string;
  subtitle?: string;
  description?: string;
  price: string;
  originalPrice?: string;
  rating?: number;
  reviewsCount?: number;
  badge?: string;
  badgeVariant?: "emerald" | "rose" | "indigo" | "amber" | "zinc";
  inStock?: boolean;
  image?: React.ReactNode;
  colors?: ProductColorOption[];
  defaultColorIndex?: number;
  onColorChange?: (color: ProductColorOption, index: number) => void;
  onAddToCart?: () => void;
  onBuyNow?: () => void;
  onQuickView?: () => void;
  onFavoriteToggle?: (isLiked: boolean) => void;
  interactive?: boolean;
}

const badgeColorStyles: Record<string, string> = {
  emerald: "bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border-emerald-500/20",
  rose: "bg-rose-500/15 text-rose-600 dark:text-rose-400 border-rose-500/20",
  indigo: "bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 border-indigo-500/20",
  amber: "bg-amber-500/15 text-amber-600 dark:text-amber-400 border-amber-500/20",
  zinc: "bg-zinc-500/15 text-zinc-700 dark:text-zinc-300 border-zinc-500/20",
};

export function ProductCard({
  className,
  variant = "standard",
  title,
  subtitle,
  description,
  price,
  originalPrice,
  rating,
  reviewsCount,
  badge,
  badgeVariant = "emerald",
  inStock = true,
  image,
  colors,
  defaultColorIndex = 0,
  onColorChange,
  onAddToCart,
  onBuyNow,
  onQuickView,
  onFavoriteToggle,
  interactive = false,
}: ProductCardProps) {
  const [liked, setLiked] = useState(false);
  const [selectedColorIdx, setSelectedColorIdx] = useState(defaultColorIndex);

  const handleFavoriteClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newLiked = !liked;
    setLiked(newLiked);
    onFavoriteToggle?.(newLiked);
  };

  const handleColorSelect = (color: ProductColorOption, idx: number, e: React.MouseEvent) => {
    e.stopPropagation();
    setSelectedColorIdx(idx);
    onColorChange?.(color, idx);
  };

  if (variant === "horizontal") {
    return (
      <article
        className={cn(
          "w-full rounded-2xl bg-primary/[0.008] border border-primary/20 p-4 flex flex-col sm:flex-row items-center gap-4 text-foreground transition-all duration-200",
          interactive && "hover:shadow-md hover:border-primary/50 hover:-translate-y-0.5",
          className
        )}
      >
        {/* Thumbnail Image */}
        <div className="size-24 rounded-2xl bg-primary/10 border border-primary/20 shrink-0 flex items-center justify-center overflow-hidden">
          {image || <span className="text-3xl font-bold">🛍️</span>}
        </div>

        {/* Content */}
        <div className="flex-1 space-y-1 text-center sm:text-left min-w-0">
          <div className="flex items-center justify-center sm:justify-start gap-2 flex-wrap">
            {badge && (
              <span
                className={cn(
                  "px-2 py-0.5 rounded-md text-[10px] font-extrabold uppercase border",
                  badgeColorStyles[badgeVariant] || badgeColorStyles.emerald
                )}
              >
                {badge}
              </span>
            )}
            {rating !== undefined && (
              <span className="text-xs font-semibold text-amber-500 flex items-center gap-1">
                <Star className="size-3 fill-amber-500" /> {rating}
              </span>
            )}
          </div>
          <h4 className="text-base font-extrabold text-foreground line-clamp-1">{title}</h4>
          {description && (
            <p className="text-xs text-muted-foreground line-clamp-1">{description}</p>
          )}
        </div>

        {/* Price & Action */}
        <div className="flex items-center gap-4 shrink-0 border-t sm:border-t-0 sm:border-l border-border/60 pt-3 sm:pt-0 sm:pl-4 w-full sm:w-auto justify-between sm:justify-end">
          <div className="text-left sm:text-right">
            <span className="text-lg font-bold text-foreground">{price}</span>
            {originalPrice && (
              <p className="text-xs text-muted-foreground line-through">{originalPrice}</p>
            )}
          </div>
          {onAddToCart && (
            <button
              type="button"
              onClick={onAddToCart}
              className="size-10 rounded-xl bg-primary text-primary-foreground flex items-center justify-center hover:opacity-90 transition-opacity active:scale-95 shadow-xs"
            >
              <Plus className="size-5" />
            </button>
          )}
        </div>
      </article>
    );
  }

  return (
    <article
      className={cn(
        "w-full rounded-2xl bg-primary/[0.008] border border-primary/20 overflow-hidden flex flex-col justify-between text-foreground transition-all duration-200 group",
        interactive && "hover:shadow-lg hover:border-primary/50 hover:-translate-y-1",
        className
      )}
    >
      {/* Image Preview Area */}
      <div className="relative aspect-4/3 w-full bg-gradient-to-br from-primary/10 via-primary/5 to-transparent flex items-center justify-center p-0 overflow-hidden">
        {badge && (
          <span
            className={cn(
              "absolute top-3 left-3 px-2.5 py-1 rounded-full text-[10px] font-extrabold uppercase tracking-wider border z-20",
              badgeColorStyles[badgeVariant] || badgeColorStyles.emerald
            )}
          >
            {badge}
          </span>
        )}

        {inStock !== undefined && (
          <div className="absolute top-3 right-3 flex items-center gap-1 px-2 py-0.5 rounded-md bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 text-[10px] font-extrabold z-20">
            <CheckCircle2 className="size-3" /> {inStock ? "In Stock" : "Out of Stock"}
          </div>
        )}

        {onFavoriteToggle && (
          <button
            type="button"
            onClick={handleFavoriteClick}
            className={cn(
              "absolute right-3 p-2 rounded-full bg-background/80 backdrop-blur-xs border border-border text-muted-foreground hover:text-rose-500 transition-colors shadow-2xs z-20",
              inStock !== undefined ? "top-10" : "top-3"
            )}
          >
            <Heart className={cn("size-4", liked && "fill-rose-500 text-rose-500")} />
          </button>
        )}

        {/* Product Visual */}
        <div className="w-full h-full flex items-center justify-center group-hover:scale-105 transition-transform duration-300">
          {image || <span className="text-4xl font-bold">📦</span>}
        </div>
      </div>

      {/* Body Content */}
      <div className="p-4 pb-2 flex-1 flex flex-col justify-between">
        <div className="space-y-1">
          <div className="flex items-center justify-between text-xs text-muted-foreground mb-1">
            {subtitle && <span className="font-semibold text-primary">{subtitle}</span>}
            {rating !== undefined && (
              <span className="flex items-center gap-1 font-semibold text-amber-500 ml-auto">
                <Star className="size-3.5 fill-amber-500" /> {rating}
                {reviewsCount !== undefined && (
                  <span className="text-muted-foreground font-normal">({reviewsCount})</span>
                )}
              </span>
            )}
          </div>

          <h3 className="text-base font-extrabold text-foreground line-clamp-1">{title}</h3>
          {description && (
            <p className="text-xs text-muted-foreground line-clamp-2">{description}</p>
          )}
        </div>

        {/* Color Options Swatches */}
        {colors && colors.length > 0 && (
          <div className="flex items-center justify-between pt-3 mt-2 border-t border-border/40">
            <span className="text-[11px] font-semibold text-muted-foreground">Color</span>
            <div className="flex items-center gap-1.5">
              {colors.map((col, idx) => (
                <button
                  key={col.name || idx}
                  type="button"
                  title={col.name}
                  onClick={(e) => handleColorSelect(col, idx, e)}
                  className={cn(
                    "size-3.5 rounded-full border transition-all",
                    col.value,
                    selectedColorIdx === idx
                      ? "ring-2 ring-primary/30 ring-offset-1 scale-110"
                      : "opacity-75 hover:opacity-100"
                  )}
                />
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Footer / Actions */}
      <div className="p-4 pt-2 flex items-center justify-between border-t border-border/40 mt-1">
        <div>
          <span className="text-lg font-bold text-foreground">{price}</span>
          {originalPrice && (
            <span className="text-xs text-muted-foreground line-through ml-2">
              {originalPrice}
            </span>
          )}
        </div>

        <div className="flex items-center gap-2">
          {onQuickView && (
            <button
              type="button"
              onClick={onQuickView}
              className="px-3 py-2 rounded-xl border border-primary/30 bg-background hover:bg-primary/10 hover:text-primary hover:border-primary/50 text-foreground text-xs font-semibold flex items-center gap-1.5 transition-colors active:scale-95 cursor-pointer"
            >
              <Eye className="size-3.5" /> Quick View
            </button>
          )}

          {onAddToCart && (
            <button
              type="button"
              onClick={onAddToCart}
              className="px-3.5 py-2 rounded-xl bg-primary text-primary-foreground text-xs font-semibold flex items-center gap-1.5 hover:opacity-90 transition-opacity active:scale-95 shadow-xs"
            >
              <ShoppingCart className="size-3.5" /> Add
            </button>
          )}

          {onBuyNow && (
            <button
              type="button"
              onClick={onBuyNow}
              className="px-3.5 py-2 rounded-xl bg-primary text-primary-foreground text-xs font-semibold flex items-center gap-1.5 hover:opacity-90 transition-opacity active:scale-95 shadow-xs"
            >
              <Zap className="size-3.5" /> Buy Now
            </button>
          )}
        </div>
      </div>
    </article>
  );
}

import { Slot } from "@radix-ui/react-slot";
import * as React from "react";

import { cn } from "@/lib/utils";
import { badgeVariants } from "./badge-variants";

type BadgeVariant = "default" | "secondary" | "destructive" | "outline";

type BadgeProps = React.HTMLAttributes<HTMLElement> & {
  className?: string;
  variant?: BadgeVariant;
  asChild?: boolean;
};

function Badge({
  className,
  variant = "default",
  asChild = false,
  ...props
}: BadgeProps) {
  const Comp = asChild ? Slot : "span";

  return (
    <Comp
      data-slot="badge"
      className={cn(badgeVariants({ variant }), className)}
      {...props}
    />
  );
}

export { Badge };

import { cva } from "class-variance-authority";

export const badgeVariants = cva(
  "inline-flex items-center justify-center rounded-md border px-2 py-0.5 text-xs font-medium w-fit whitespace-nowrap shrink-0 [&>svg]:size-3 gap-1 [&>svg]:pointer-events-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive transition-[color,box-shadow] overflow-hidden",
  {
    variants: {
      variant: {
        default:
          "border-transparent bg-primary text-primary-foreground [a&]:hover:bg-primary/90",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground [a&]:hover:bg-secondary/90",
        destructive:
          "border-transparent bg-destructive text-white [a&]:hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "text-foreground [a&]:hover:bg-accent [a&]:hover:text-accent-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

