const softTokens = (color?: string) =>
  ({
    "--tbl-accent": getAccentColor(color),
    "--tbl-well":
      "color-mix(in oklab, var(--tbl-accent) 5%, color-mix(in oklab, var(--foreground) 5%, var(--card)))",
    "--tbl-row-hover": "color-mix(in oklab, var(--tbl-accent) 4%, var(--card))",
